{"file_path":"/tmp/bot-p622r1-dev/work/dev-single-json-schema-1/validate.mjs","content":"#!/usr/bin/env node
// validate.mjs — 校验内嵌样例数据 {"port":8080,"enabled":true}
// 规则:
//   1. port 必须是合法端口: 1–65535 之间的整数
//   2. enabled 必须是布尔值 (true / false)
// 退出码: 0 = 全部通过, 1 = 存在校验失败

const sample = { port: 8080, enabled: true };

const results = [];

function check(name, pass, detail) {
  results.push({ name, pass, detail });
}

// ---- 规则 1: port 是合法端口 ----
{
  const name = "port 是 1–65535 之间的整数";
  const port = sample.port;
  const isInteger = Number.isInteger(port);
  const inRange = isInteger && port >= 1 && port <= 65535;
  const pass = inRange;
  const detail = `port=${JSON.stringify(port)} (类型 ${typeof port}), 是整数: ${isInteger}, 在 1–65535 范围内: ${inRange}`;
  check(name, pass, detail);
}

// ---- 规则 2: enabled 是布尔值 ----
{
  const name = "enabled 是布尔值 (true/false)";
  const enabled = sample.enabled;
  const pass = typeof enabled === "boolean";
  const detail = `enabled=${JSON.stringify(enabled)} (类型 ${typeof enabled}), 是否布尔: ${pass}`;
  check(name, pass, detail);
}

// ---- 输出 ----
console.log(`样例数据: ${JSON.stringify(sample)}`);
console.log("");
for (const r of results) {
  console.log(`[${r.pass ? "通过" : "失败"}] ${r.name} — ${r.detail}`);
}
const allPass = results.every((r) => r.pass);
console.log("");
console.log(
  allPass
    ? "最终结论: 全部校验通过"
    : `最终结论: 校验失败 (${results.filter((r) => !r.pass).length} 项未通过)`
);

process.exit(allPass ? 0 : 1);
"}

